<?php require_once '../includes/functions.php';require_once '../includes/openai.php';require_staff();$pdo=db();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$topic=post('topic');$difficulty=post('difficulty');$count=max(3,min(20,(int)($_POST['question_count']??5)));$category=(int)($_POST['category_id']??0);$time=max(1,(int)($_POST['time_limit']??10));if(!$topic||!$category)$errors[]='Topic and category are required.';else{try{$generated=generate_quiz_with_ai($topic,$difficulty,$count);$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO quizzes(category_id,title,description,time_limit_minutes,allow_retakes,is_published,created_by) VALUES(?,?,?,?,1,0,?)');$s->execute([$category,$generated['title'],$generated['description'],$time,user()['id']]);$quizId=(int)$pdo->lastInsertId();$qStmt=$pdo->prepare('INSERT INTO questions(quiz_id,question_text) VALUES(?,?)');$oStmt=$pdo->prepare('INSERT INTO options(question_id,option_text,is_correct) VALUES(?,?,?)');foreach($generated['questions'] as $q){if(count($q['options'])!==4)throw new RuntimeException('AI produced invalid options.');$qStmt->execute([$quizId,$q['question']]);$qid=$pdo->lastInsertId();foreach($q['options'] as $i=>$option)$oStmt->execute([$qid,$option,$i===(int)$q['correct_index']]);}$pdo->commit();flash('success','AI quiz draft created. Review all questions before publishing.');redirect("questions.php?quiz_id=$quizId");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}}
$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$pageTitle='AI Quiz Generator';require '../includes/header.php';?>
<form class="form-card" method="post"><h1>Generate Quiz with AI</h1><p class="muted">The generated quiz is saved as a draft. A teacher must review accuracy and publish it.</p><?php foreach($errors as $x):?><p class="error"><?=e($x)?></p><?php endforeach;?><?=csrf_field()?><label>Topic</label><input name="topic" placeholder="Example: PHP loops and arrays" value="<?=e($_POST['topic']??'')?>" required><label>Category</label><select name="category_id" required><option value="">Select</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Difficulty</label><select name="difficulty"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select><label>Number of Questions (3-20)</label><input type="number" name="question_count" min="3" max="20" value="5"><label>Time Limit (minutes)</label><input type="number" name="time_limit" min="1" value="10"><br><br><button>Generate Draft</button></form>
<?php require '../includes/footer.php';?>
